const texto = $('Telegram Trigger1').first().json.message.text;
const regex = /^(\d{2})-(\d{2})-(\d{4})$/;
const match = texto.match(regex);

let fecha_valida = false;

if (match) {
  const [, dd, mm, aaaa] = match.map(Number);
  const fecha = new Date(aaaa, mm - 1, dd);

  const esFechaReal = fecha.getDate() === dd && fecha.getMonth() === mm - 1 && fecha.getFullYear() === aaaa;

  if (esFechaReal) {
    const hoy = new Date();
    hoy.setHours(0, 0, 0, 0);

    const limite = new Date(hoy);
    limite.setFullYear(limite.getFullYear() + 1);

    fecha_valida = fecha >= hoy && fecha <= limite;
  }
}

return { fecha_valida, fecha_ingresada: texto };

