const items = $input.all();

if (items.length === 0) {
  return [{ 
    json: { 
      mensaje_telegram: "📭 Actualmente no tienes tutorías registradas para este ID." 
    } 
  }];
}

const listaTutorias = items.map(item => {
  const tutoria = item.json;

  let estadoEmoji = "⏳";
  if (tutoria.estado.toLowerCase() === "cancelada") estadoEmoji = "❌";
  if (tutoria.estado.toLowerCase() === "completada" || tutoria.estado.toLowerCase() === "activa") estadoEmoji = "✅";

  return `🆔 ${tutoria.id_tutoria} | 📘 ${tutoria.materia} (${estadoEmoji} Estado: ${tutoria.estado})`;
}).join("\n");

const mensajeFinal = `📋 *Este es el detalle de las tutorías solicitadas:*\n\n${listaTutorias}\n\n👉 *Ingresa el ID de la tutoría a Cancelar:*`;

return [{ 
  json: { 
    mensaje_telegram: mensajeFinal 
  } 
}];

